INSERT INTO public.fandom_directory(tag_id,media_categories,subcategory,aliases,franchise)
SELECT t.id,seed.media_categories,seed.subcategory,seed.aliases,seed.franchise
FROM seed JOIN public.tags t ON t.category='fandom' AND lower(t.name)=lower(seed.name)
WHERE t.status IN ('canonical','community')
ON CONFLICT(tag_id) DO NOTHING;
